"""Build exact-key D156 role-to-parent-domain fit review; audit-only."""
import json
from collections import Counter
from datetime import date
from pathlib import Path
LANE=Path(__file__).resolve().parent; QUEUE=LANE/'D085_D168_role_fit_queue_2026_10_05.json'; OUT_JSON=LANE/'D156_role_domain_fit_review_2026_10_05.json'; OUT_MD=LANE/'D156_role_domain_fit_review_2026_10_05.md'
SOURCES={
 'QUEUE_TASK_PROFILE':{'publisher':'Checked-in role/domain audit queue','url':'D085_D168_role_fit_queue_2026_10_05.json','locator':'Exact D156 role keys, recorded task descriptions and parent scope.','supports':'The tasks actually evaluated.','limit':'The queue is the mapping under review, not independent verification of the occupation.'},
 'FIG_SURVEYOR_FUNCTIONS':{'publisher':'International Federation of Surveyors (FIG)','url':'https://fig.net/resources/publications/figpub/pub66/figpub66.asp','locator':'FIG Definition of the Functions of the Surveyor: measuring/representing land and 3-D objects; assembling and interpreting land/geographic information; planning and administration of land, sea and structures; construction measurement and cost estimation are separately named functions.','supports':'Global boundaries among surveying, geospatial information, marine work and construction-cost functions.','limit':'FIG describes a broad professional field; licensing and specific cadastral authority are jurisdiction-dependent.'},
 'FIG_CADASTRE':{'publisher':'International Federation of Surveyors (FIG), Commission 7','url':'https://www.fig.net/organisation/comm/7/library/reports/cadastre/statement_on_cadastre.html','locator':'FIG Statement on the Cadastre: parcel-based land-information system; cadastral surveying identifies, demarcates, measures and maps legal parcel boundaries; cadastres may support land administration, fiscal valuation/tax and land-use management.','supports':'Cadastral boundary/parcel duties and the limited relationship between cadastral records, valuation and taxation.','limit':'The statement does not prescribe one uniform cadastre; national systems and legally reserved survey functions differ.'},
}
S='supported'; C='conditional'; U='unsupported_for_domain'
DECISIONS={
 'D156|Geodetic Surveyors':(S,'Measures large areas of the Earth using GNSS, satellite observations and lidar; this is direct geodetic survey data acquisition within the parent scope.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|Surveyors':(S,'Measures land features and determines property boundaries for engineering, mapping, mining and land evaluation, directly matching land surveying and cadastral mapping.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS','FIG_CADASTRE']),
 'D156|cadastral technician':(S,'Converts survey measurements into cadastral maps and records parcel boundaries, ownership and land use, directly matching cadastral mapping.',['QUEUE_TASK_PROFILE','FIG_CADASTRE']),
 'D156|cartographer':(C,'Creates maps for many subjects, including topographic maps, but the stored task does not establish a land-survey or cadastral data focus for every assignment.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|geographic information systems specialist':(S,'Processes geospatial/land information into digital maps and geomodels; the scope explicitly includes GIS specialists translating land measurements into digital records.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|hydrographic surveyor':(C,'Measures and maps marine environments and underwater topography. It is surveying, but the parent name is land/cadastral mapping; retain only where the catalogue intends to include hydrographic surveying of waterways, not as a cadastral occupation.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|land surveyor':(S,'Measures positions and distances on construction sites, the direct land-survey task named by the domain.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|marine surveyor':(U,'Inspects ships and offshore facilities for maritime regulatory compliance; it does not perform land measurement, cadastral boundary determination or geospatial land records.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|mine surveyor':(S,'Prepares and maintains mining plans and records physical mine progress and production; this is a recognized surveying application explicitly within the parent description.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|quantity surveyor':(U,'Manages construction-project costs, resources, quality and delivery. The task is quantity/cost management, not measuring land or creating cadastral/geospatial records.',['QUEUE_TASK_PROFILE','FIG_SURVEYOR_FUNCTIONS']),
 'D156|real estate surveyor':(C,'Assesses property value for taxation. Cadastres can support fiscal valuation/tax, but the task describes valuation rather than surveying or maintaining parcel-boundary records; retain only if this catalogue intentionally includes cadastral valuation roles.',['QUEUE_TASK_PROFILE','FIG_CADASTRE']),
}
def main():
 q=json.loads(QUEUE.read_text(encoding='utf-8'))['unresolved_rows']; rows=[r for r in q if r['domain_id']=='D156']; by={r['role_key']:r for r in rows}
 if len(by)!=len(rows) or set(by)!=set(DECISIONS): raise SystemExit('D156 exact-key mismatch; refusing partial generation.')
 decisions=[]
 for key,(fit,why,refs) in DECISIONS.items():
  r=by[key]; decisions.append({'role_key':key,'role_name':r['role_name'],'task_evidence':r['role_description'],'esco_uri':(r.get('esco_occupation_uris') or [None])[0],'onet_codes':r.get('onet_occupation_codes',[]),'domain_fit':fit,'rationale':why,'source_refs':refs})
 tally=Counter(x['domain_fit'] for x in decisions)
 payload={'schema_version':'1.0','audit_date':date.today().isoformat(),'domain_id':'D156','domain_name':rows[0]['domain_name'],'scope':rows[0]['domain_scope'],'method':'Exact-key comparison of stored tasks to land-survey/cadastral parent scope. Titles, ISCO/subgroup placement and frequency do not establish fit. FIG international definitions clarify surveyor functions and cadastral boundaries; jurisdiction-specific licensing is not inferred. No role-to-specialization assignment is made.','counts':{'mappings_reviewed':len(decisions),'supported':tally[S],'conditional':tally[C],'unsupported_for_domain':tally[U],'unresolved':tally['unresolved']},'decisions':decisions,'sources':SOURCES,'correction_proposals':[{'role_key':'D156|marine surveyor','action':'remove_from_parent_domain','candidate_transfer_domain':None,'evidence_basis':'The stored task is vessel/offshore-facility regulatory inspection, not land/cadastral surveying; no destination is asserted.'},{'role_key':'D156|quantity surveyor','action':'remove_from_parent_domain','candidate_transfer_domain':None,'evidence_basis':'The stored task is construction cost/resource management rather than land surveying or cadastral mapping.'}],'separate_coverage_candidates':[],'notes':['Hydrographic surveying is kept conditional because it is a genuine surveying field but not the land/cadastral core; the parent scope mentions waterways, so the catalogue owner must decide whether that cross-boundary inclusion is intended.','Real-estate valuation may interact with cadastral fiscal records, but valuation is not itself a land-boundary survey. The mapping remains conditional unless cadastral valuation is an explicit product scope.','No Nigeria-specific role variant is inferred; national legal authority and licensing remain jurisdiction-specific.','No canonical role/domain/subgroup data or role-to-specialization assignment was changed.']}
 OUT_JSON.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 lines=[f"# D156 role-to-parent-domain fit review — {payload['audit_date']}",'',f"Scope: {payload['scope']}",'',f"- Exact queued roles reviewed: **{len(decisions)}**",f"- Supported: **{tally[S]}**",f"- Conditional: **{tally[C]}**",f"- Unsupported for this parent: **{tally[U]}**",f"- Unresolved: **{tally['unresolved']}**",'','| Exact role key | Recorded task evidence | Parent fit | Rationale |','|---|---|---|---|']
 for x in decisions: lines.append(f"| `{x['role_key']}` | {x['task_evidence'].replace('|','\\|').replace(chr(10),' ')} | {x['domain_fit']} | {x['rationale'].replace('|','\\|')} |")
 lines+=['','## Non-canonical correction proposals','']+[f"- `{x['role_key']}` — {x['action']}: {x['evidence_basis']} No canonical change made." for x in payload['correction_proposals']]+['','## Sources and limitations','']+[f"- **{k} — {v['publisher']}**: [{v['url']}]({v['url']}). {v['locator']} Supports: {v['supports']} Limit: {v['limit']}" for k,v in SOURCES.items()]+['','## Audit notes','']+[f'- {n}' for n in payload['notes']]
 OUT_MD.write_text('\n'.join(lines)+'\n',encoding='utf-8'); print(json.dumps(payload['counts'],indent=2))
if __name__=='__main__': main()
